const rows = $input.all().map(item => item.json);

const num = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

const totalShipments = rows.length;
const currentCost = rows.reduce((s, r) => s + num(r.Current_Cost), 0);
const optimizedCost = rows.reduce((s, r) => s + num(r.Optimized_Cost), 0);
const totalSaving = currentCost - optimizedCost;
const savingPercentage = currentCost ? (totalSaving / currentCost) * 100 : 0;

const vehicleMap = {};

for (const r of rows) {
  const vehicle = r.Optimized_Vehicle || 'Unknown';

  if (!vehicleMap[vehicle]) {
    vehicleMap[vehicle] = {
      vehicle,
      shipments: 0,
      totalLoadKg: 0,
      utilizationSum: 0
    };
  }

  vehicleMap[vehicle].shipments += 1;
  vehicleMap[vehicle].totalLoadKg += num(r.Load_KG);
  vehicleMap[vehicle].utilizationSum += num(r['Vehicle_Utilization_%']);
}

const vehicleUtilization = Object.values(vehicleMap)
  .map(v => ({
    vehicle: v.vehicle,
    shipments: v.shipments,
    totalLoadKg: Number(v.totalLoadKg.toFixed(2)),
    averageUtilization: Number((v.utilizationSum / v.shipments).toFixed(2))
  }))
  .sort((a, b) => b.averageUtilization - a.averageUtilization);

const highestUtilized = vehicleUtilization[0] || null;

const summaryText = `
Total shipments: ${totalShipments}
Current transportation cost: ${currentCost.toFixed(2)}
Optimized transportation cost: ${optimizedCost.toFixed(2)}
Total cost saving: ${totalSaving.toFixed(2)}
Cost saving percentage: ${savingPercentage.toFixed(2)}%

Vehicle utilization:
${vehicleUtilization.map(v =>
  `${v.vehicle}: ${v.shipments} shipments, ${v.totalLoadKg} kg total load, ${v.averageUtilization}% average utilization`
).join('\n')}

Highest average utilization:
${highestUtilized ? `${highestUtilized.vehicle} at ${highestUtilized.averageUtilization}%` : 'Not available'}
`.trim();

return [{
  json: {
    totalShipments,
    currentCost: Number(currentCost.toFixed(2)),
    optimizedCost: Number(optimizedCost.toFixed(2)),
    totalSaving: Number(totalSaving.toFixed(2)),
    savingPercentage: Number(savingPercentage.toFixed(2)),
    vehicleUtilization,
    highestUtilized,
    summaryText
  }
}];
